create table if not exists public.feature_upgrade_requests(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,feature_key text not null references public.feature_catalog(feature_key) on delete restrict,requested_by uuid references auth.users(id) on delete set null,status text not null default 'requested' check(status in('requested','contacted','quoted','approved','declined','cancelled','activated')),note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists feature_upgrade_open_uq on public.feature_upgrade_requests(tenant_id,feature_key) where status in('requested','contacted','quoted','approved');alter table public.feature_upgrade_requests enable row level security;
create policy feature_upgrade_tenant_read on public.feature_upgrade_requests for select to authenticated using(public.can_access_tenant(tenant_id,array['super_admin','admin']::public.role_key[]) or public.is_platform_staff(null));
create or replace function public.request_feature_upgrade(p_tenant uuid,p_feature text,p_note text default null) returns uuid language plpgsql security definer set search_path=public as $$declare rid uuid;begin if auth.uid() is null then raise exception 'authentication_required';end if;if not public.can_access_tenant(p_tenant,array['super_admin','admin']::public.role_key[]) then raise exception 'forbidden';end if;if not exists(select 1 from public.feature_catalog where feature_key=p_feature and default_enabled=false) then raise exception 'feature_not_upgradeable';end if;if public.has_entitlement(p_tenant,p_feature) then raise exception 'already_active';end if;select id into rid from public.feature_upgrade_requests where tenant_id=p_tenant and feature_key=p_feature and status in('requested','contacted','quoted','approved') order by created_at desc limit 1;if rid is not null then return rid;end if;insert into public.feature_upgrade_requests(tenant_id,feature_key,requested_by,note) values(p_tenant,p_feature,auth.uid(),nullif(left(trim(coalesce(p_note,'')),500),'')) returning id into rid;insert into public.event_logs(tenant_id,category,event_name,summary_fa,metadata) values(p_tenant,'sales','feature.upgrade_requested','درخواست فعال‌سازی قابلیت قراردادی ثبت شد.',jsonb_build_object('feature_key',p_feature,'request_id',rid));return rid;end$$;revoke all on function public.request_feature_upgrade(uuid,text,text) from public,anon;grant execute on function public.request_feature_upgrade(uuid,text,text) to authenticated;
insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values('platform.upgrade_center','امکانات قابل ارتقا','قابلیت‌های قراردادی خریداری‌نشده مخفی نمی‌شوند؛ در Upgrade Center با وضعیت قفل، توضیح ارزش و امکاناتی که اضافه می‌کنند نمایش داده می‌شوند. مدیر مشتری فقط می‌تواند درخواست فعال‌سازی ثبت کند و فعال‌سازی واقعی همچنان در اختیار مدیر پلتفرم است.','قابلیت قفل‌شده نباید با URL یا درخواست مستقیم قابل استفاده باشد. نمایش Preview جای Entitlement سمت سرور را نمی‌گیرد.','Upgrade Center','Unpurchased contractual capabilities remain visible as locked upgrade cards explaining their value and added abilities. Tenant admins may request activation, while actual entitlement remains controlled by the platform operator.','Locked features must not become usable through direct URLs or requests. Preview visibility never replaces server-side entitlement enforcement.',true) on conflict(help_key) do update set title_fa=excluded.title_fa,body_fa=excluded.body_fa,warning_fa=excluded.warning_fa,title_en=excluded.title_en,body_en=excluded.body_en,warning_en=excluded.warning_en,active=true;